"""Regression tests that replace every updater command with an isolated stub.

Run: uv run --no-project --offline python -B -m unittest discover -s tests -v
"""

import json
import os
from pathlib import Path
import shutil
import subprocess
import sys
import tempfile
import textwrap
import unittest


REPO = Path(__file__).resolve().parents[1]
ZSH = shutil.which("zsh")
NODE = shutil.which("node")
NO_MANIFEST = object()

STUB = "#!" + sys.executable + "\n" + textwrap.dedent("""\
    import json
    import os
    from pathlib import Path
    import sys

    name = Path(sys.argv[0]).name
    args = sys.argv[1:]
    with open(os.environ["HC_TEST_EVENTS"], "a") as log:
        log.write(json.dumps([name, *args]) + "\\n")
    command = " ".join([name, *args])
    failure = json.loads(os.environ["HC_TEST_FAILURES"]).get(command, 0)
    if failure:
        print("Simulated failure: " + command, file=sys.stderr)
        sys.exit(failure)
    if name == "yarn" and args[:2] == ["global", "dir"]:
        print(os.environ["HC_TEST_YARN_DIR"])
    if name == "gpg":
        print(os.environ.get("HC_TEST_GPG_OUTPUT", ""), end="")
    """)

HARNESS = r'''
log_info() { print -r -- "INFO: $*"; }
log_warning() { print -r -- "WARNING: $*"; }
log_error() { print -ru2 -- "ERROR: $*"; }
log_success() { print -r -- "SUCCESS: $*"; }
bold() { print -r -- "$*"; }
fg_yellow() { print -r -- "$*"; }
source "$1"
source "$2"
shift 2
if [[ ${HC_TEST_HELPER:-0} == 1 ]]; then
  run_helper_test() {
    local -a _hc_update_failures=()
    local -i _hc_update_interrupted=0
    _hc::run_update_step "$@"
    local run_exit_code=$?
    print -r -- "RECORDED: ${(j:; :)_hc_update_failures}"
    return "$run_exit_code"
  }
  run_helper_test "$@"
  exit $?
fi
if [[ ${HC_TEST_STRICT:-0} == 1 ]]; then
  setopt errexit err_return nounset pipefail
  if hc-update-everything "$@"; then
    run_exit_code=0
  else
    run_exit_code=$?
  fi
  [[ -o errexit && -o err_return && -o nounset && -o pipefail ]] || exit 99
  exit "$run_exit_code"
fi
hc-update-everything "$@"
exit $?
'''


@unittest.skipUnless(ZSH, "Zsh is required")
class UpdateEverythingTests(unittest.TestCase):
    def run_updater(
        self,
        *args,
        failures=None,
        manifest=NO_MANIFEST,
        interactive=False,
        missing=(),
        omz=True,
        gpg_output="",
        strict=False,
        helper=False,
    ):
        if manifest is not NO_MANIFEST and not NODE:
            self.skipTest("Node is required to check Yarn manifests")
        with tempfile.TemporaryDirectory(prefix="hc updater tests ") as temp:
            root = Path(temp)
            bin_dir = root / "bin"
            bin_dir.mkdir()
            for name in (
                "brew", "uv", "rustup", "gh", "npm", "yarn", "gem", "gpg",
                "mackup", "sudo", "zsh",
            ):
                if name not in missing:
                    tool = bin_dir / name
                    tool.write_text(STUB)
                    tool.chmod(0o755)
            if NODE:
                (bin_dir / "node").symlink_to(Path(NODE).resolve())
            yarn_dir = root / "yarn global"
            yarn_dir.mkdir()
            if manifest is not NO_MANIFEST:
                content = manifest if isinstance(manifest, str) else json.dumps(manifest)
                (yarn_dir / "package.json").write_text(content)

            events_file = root / "events.jsonl"
            env = os.environ.copy()
            env.update({
                # No real updater command can be found through PATH.
                "PATH": str(bin_dir),
                "ZDOTDIR": str(root),
                "TERM": "dumb",
                "HC_TEST_EVENTS": str(events_file),
                "HC_TEST_FAILURES": json.dumps(failures or {}),
                "HC_TEST_YARN_DIR": str(yarn_dir),
                "HC_TEST_GPG_OUTPUT": gpg_output,
                "HC_TEST_STRICT": "1" if strict else "0",
                "HC_TEST_HELPER": "1" if helper else "0",
            })
            for key in ("FPATH", "fpath", "NODE_OPTIONS", "NODE_PATH"):
                env.pop(key, None)
            if omz:
                env["ZSH"] = str(root / "oh my zsh")
            else:
                env.pop("ZSH", None)
            command = [str(Path(ZSH).resolve()), "-f"]
            if interactive:
                command.append("-i")
            command.extend([
                "-c", HARNESS, "updater-test",
                str(REPO / "shell/functions/hc.zsh"),
                str(REPO / "shell/functions/dot.zsh"),
                *args,
            ])
            result = subprocess.run(
                command, env=env, cwd=root, text=True,
                capture_output=True, stdin=subprocess.DEVNULL, timeout=15,
            )
            events = (
                [json.loads(line) for line in events_file.read_text().splitlines()]
                if events_file.exists() else []
            )
            return result, events

    def assert_failed(self, result, label):
        self.assertEqual(result.returncode, 1, result.stdout + result.stderr)
        self.assertIn(label, result.stderr)
        self.assertIn("failed step(s)", result.stderr)
        self.assertNotIn("Done!", result.stdout)

    def test_help_does_not_run_updates(self):
        for option in ("--help", "-h"):
            with self.subTest(option=option):
                result, events = self.run_updater(option)
                self.assertEqual(result.returncode, 0, result.stderr)
                self.assertIn("Run a system software update last", result.stdout)
                self.assertEqual(events, [])

    def test_all_arguments_are_validated_before_any_update(self):
        for args in (
            ("--unknown",), ("--systematic",), ("value--help",),
            ("--system", "--bad"), ("--help", "--bad"), ("positional",),
        ):
            with self.subTest(args=args):
                result, events = self.run_updater(*args)
                self.assertEqual(result.returncode, 2)
                self.assertIn("Unknown option or argument", result.stderr)
                self.assertEqual(events, [])

    def test_success_without_optional_updates_does_not_restart_a_script(self):
        result, events = self.run_updater()
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertIn("Done!", result.stdout)
        self.assertIn(["brew", "upgrade", "--no-ask"], events)
        self.assertIn(["npm", "update", "--global", "--no-fund"], events)
        self.assertIn(["gem", "update", "--system"], events)
        self.assertIn("Skipping Yarn: no global packages", result.stdout)
        self.assertNotIn(["zsh"], events)
        self.assertFalse(any(event[0] == "sudo" for event in events))
        self.assertFalse(any(event[0] == "mackup" for event in events))
        self.assertFalse(any("--greedy-latest" in event for event in events))

    def test_interactive_success_restarts_only_after_all_steps(self):
        result, events = self.run_updater(
            "--system", "--brew-greedy-latest", interactive=True,
        )
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertIn(["brew", "upgrade", "--no-ask", "--greedy-latest"], events)
        self.assertEqual(events[-1], ["zsh"])
        self.assertEqual(events[-2], [
            "sudo", "softwareupdate", "--install", "--all", "--verbose",
            "--force", "--agree-to-license",
        ])
        self.assertFalse(any(event[:2] == ["sudo", "gem"] for event in events))

    def test_metadata_failure_does_not_block_any_later_updates(self):
        result, events = self.run_updater(
            "--system", "--brew-greedy-latest", failures={"brew update": 7},
        )
        self.assert_failed(result, "brew update (exit 7)")
        self.assertEqual([event for event in events if event[0] == "brew"], [
            ["brew", "update"],
            ["brew", "bundle", "--global"],
            ["brew", "upgrade", "--no-ask"],
            ["brew", "upgrade", "--no-ask", "--greedy-latest"],
        ])
        self.assertIn(["uv", "tool", "upgrade", "--all"], events)
        self.assertIn(["gem", "update", "--system"], events)
        self.assertEqual(events[-1][0:2], ["sudo", "softwareupdate"])

    def test_bundle_failure_does_not_block_existing_package_upgrades(self):
        result, events = self.run_updater(failures={"brew bundle --global": 9})
        self.assert_failed(result, "brew bundle --global (exit 9)")
        self.assertIn(["brew", "upgrade", "--no-ask"], events)

    def test_multiple_failures_are_reported_and_interactive_shell_is_not_restarted(self):
        result, events = self.run_updater(interactive=True, failures={
            "rustup update": 3,
            "gh extension upgrade --all": 4,
            "gem update --system": 5,
        })
        self.assert_failed(result, "rustup update (exit 3)")
        for label in (
            "gh extension upgrade --all (exit 4)", "gem update --system (exit 5)",
        ):
            self.assertIn(label, result.stderr)
        self.assertIn("3 failed step(s)", result.stderr)
        self.assertNotIn(["zsh"], events)

    def test_npm_self_update_failure_does_not_block_global_updates(self):
        result, events = self.run_updater(failures={
            "npm install npm --global --no-fund": 12,
        })
        self.assert_failed(result, "npm install npm --global --no-fund (exit 12)")
        self.assertIn(["npm", "update", "--global", "--no-fund"], events)
        self.assertIn(["gem", "update", "--system"], events)

    def test_system_update_failure_is_recorded(self):
        command = "sudo softwareupdate --install --all --verbose --force --agree-to-license"
        result, events = self.run_updater("--system", failures={command: 8})
        self.assert_failed(result, "System software update (exit 8)")
        self.assertEqual(events[-1][0:2], ["sudo", "softwareupdate"])

    def test_missing_required_tool_is_a_failure_and_other_updates_continue(self):
        result, events = self.run_updater(missing=("rustup",))
        self.assert_failed(result, "rustup update (exit 127)")
        self.assertIn(["gh", "extension", "upgrade", "--all"], events)
        self.assertIn(["gpg", "--list-secret-keys"], events)

    def test_failed_shell_restart_does_not_hide_its_exit_status(self):
        result, _ = self.run_updater(interactive=True, omz=False, missing=("zsh",))
        self.assertEqual(result.returncode, 127, result.stdout + result.stderr)

    def test_gpg_query_failure_is_not_reported_as_healthy(self):
        result, events = self.run_updater("--system", failures={"gpg --list-secret-keys": 11})
        self.assert_failed(result, "GPG key check (exit 11)")
        self.assertIn("Running `GPG key check`...", result.stdout)
        self.assertNotIn("No expired GPG keys", result.stdout)
        self.assertEqual(events[-1][0:2], ["sudo", "softwareupdate"])

    def test_expired_keys_are_an_advisory(self):
        result, _ = self.run_updater(gpg_output="sec rsa4096 [expired: 2020-01-01]\n")
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertIn("Found expired GPG keys", result.stdout)
        self.assertIn("Done!", result.stdout)

    def test_missing_yarn_is_skipped(self):
        result, _ = self.run_updater(missing=("yarn",))
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertIn("Skipping Yarn: it is not installed", result.stdout)

    def test_empty_yarn_manifest_is_skipped(self):
        result, events = self.run_updater(manifest={"dependencies": {}})
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertIn("Skipping Yarn: no global packages", result.stdout)
        self.assertNotIn(["yarn", "global", "upgrade", "--non-interactive"], events)

    def test_yarn_updates_configured_packages_noninteractively(self):
        for section in ("dependencies", "devDependencies", "optionalDependencies"):
            with self.subTest(section=section):
                result, events = self.run_updater(manifest={section: {"example": "1.0.0"}})
                self.assertEqual(result.returncode, 0, result.stderr)
                self.assertIn(["yarn", "global", "upgrade", "--non-interactive"], events)

    def test_yarn_directory_failure_is_recorded(self):
        result, events = self.run_updater(failures={"yarn global dir --silent": 13})
        self.assert_failed(result, "Yarn global package updates (exit 13)")
        self.assertIn(["gem", "update", "--system"], events)

    def test_invalid_yarn_manifest_is_a_failure(self):
        result, events = self.run_updater(manifest="invalid JSON")
        self.assert_failed(result, "Yarn global package updates")
        self.assertNotIn(["yarn", "global", "upgrade", "--non-interactive"], events)
        self.assertIn(["gem", "update", "--system"], events)

    def test_yarn_upgrade_failure_is_recorded(self):
        result, _ = self.run_updater(
            manifest={"dependencies": {"example": "1.0.0"}},
            failures={"yarn global upgrade --non-interactive": 14},
        )
        self.assert_failed(result, "Yarn global package updates (exit 14)")

    def test_interrupts_stop_subsequent_updates_and_preserve_the_exit_code(self):
        for command in (
            "brew update", "uv tool upgrade --all", "npm install npm --global --no-fund",
        ):
            for exit_code in (130, 143):
                with self.subTest(command=command, exit_code=exit_code):
                    result, events = self.run_updater(
                        "--system", failures={command: exit_code},
                    )
                    self.assertEqual(result.returncode, exit_code, result.stderr)
                    self.assertEqual(events[-1], command.split())
                    self.assertIn("Update interrupted", result.stderr)
                    self.assertNotIn("Done!", result.stdout)
                    self.assertNotIn("failed step(s)", result.stderr)

    def test_caller_options_are_preserved_and_do_not_abort_independent_steps(self):
        result, events = self.run_updater(
            strict=True, omz=False, failures={"rustup update": 15},
        )
        self.assert_failed(result, "rustup update (exit 15)")
        self.assertIn(["gpg", "--list-secret-keys"], events)
        self.assertIn("Skipping the Oh My Zsh update", result.stdout)

    def test_default_label_includes_the_command_and_arguments(self):
        result, _ = self.run_updater(failures={"uv tool upgrade --all": 7})
        self.assert_failed(result, "uv tool upgrade --all (exit 7)")
        self.assertIn("Running `uv tool upgrade --all`...", result.stdout)

    def test_display_quoting_preserves_argument_boundaries(self):
        result, events = self.run_updater(
            "uv", "two words", "literal;value", helper=True,
        )
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertEqual(events, [["uv", "two words", "literal;value"]])
        self.assertIn("Running `uv 'two words' 'literal;value'`...", result.stdout)

    def test_custom_label_is_not_passed_to_the_command_and_records_failures(self):
        result, events = self.run_updater(
            "--label", "Custom update", "uv", "argument", helper=True,
            failures={"uv argument": 9},
        )
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertEqual(events, [["uv", "argument"]])
        self.assertIn("Running `Custom update`...", result.stdout)
        self.assertIn("RECORDED: Custom update (exit 9)", result.stdout)


